import { useEffect, useState } from 'react';
import EventsList from '../components/EventsList';
import { useLoaderData } from 'react-router-dom';

function EventsPage() {
  /*const [isLoading, setIsLoading] = useState(false);
  const [fetchedEvents, setFetchedEvents] = useState();
  const [error, setError] = useState();

  useEffect(() => {
    async function fetchEvents() {
      setIsLoading(true);
      const response = await fetch('http://localhost:8080/events');

      if (!response.ok) {
        setError('Fetching events failed.');
      } else {
        const resData = await response.json();
        setFetchedEvents(resData.events);
      }
      setIsLoading(false);
    }

    fetchEvents();
  }, []);

  return (
    <>
      <div style={{ textAlign: 'center' }}>
        {isLoading && <p>Loading...</p>}
        {error && <p>{error}</p>}
      </div>
      {!isLoading && fetchedEvents && <EventsList events={fetchedEvents} />}
    </>
  );*/

  const data = useLoaderData();   // We can also use this useLoaderData() to get the data inside of EventsList component

  if (data.isError){
    return <p>{data.message}</p>;
  }

  return (
    <EventsList events={data.events} />
  );
}

export default EventsPage;

export async function loader() {
  const response = await fetch('http://localhost:8080/eventds');

  if (!response.ok) {
    return {isError: true, message: 'Fetching events failed.'};
  } else {
    const resData = await response.json();
    return resData;
  }
}

// useLoader automatically resolves the promise and returns the data
